//! Generic Document identity is independent from the HTML/XML document flag.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><span id=mount></span><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://attribute-factories.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}


#[test]
fn character_splice_native_methods_all_kinds_owners_units_clones_and_old_values(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"var methods=[['appendData',1],['insertData',2],['deleteData',2],['replaceData',3]];for(var pair of methods){var d=Object.getOwnPropertyDescriptor(CharacterData.prototype,pair[0]);if(d.value.name!==pair[0]||d.value.length!==pair[1]||!d.enumerable||!d.writable||!d.configurable||Object.hasOwn(Text.prototype,pair[0]))throw 'canonical CharacterData writer descriptors';}var xml=document.implementation.createDocument(null,''),generic=new Document(),html=document.implementation.createHTMLDocument('owner'),template=xml.createElementNS('http://www.w3.org/1999/xhtml','template').content.ownerDocument;for(var owner of [document,html,xml,generic,template]){var value='A\ud83d',nodes=[owner.createTextNode(value),owner.createComment(value),owner.createProcessingInstruction('target',value)];if(owner===xml||owner===generic||owner===template)nodes.push(owner.createCDATASection(value));if(owner===document)nodes.push(document.importNode(xml.createCDATASection(value),false));for(var node of nodes){var copy=node.cloneNode(false),watch=new MutationObserver(function(){});watch.observe(node,{characterData:true,characterDataOldValue:true});if(node.appendData('\ude00B')!==undefined||node.data!=='A\ud83d\ude00B'||node.length!==4)throw 'append joins surrogate pair';if(node.insertData(2,'\ud800')!==undefined||node.data!=='A\ud83d\ud800\ude00B')throw 'insert splits pair';if(node.deleteData(2,1)!==undefined||node.data!=='A\ud83d\ude00B')throw 'delete restores pair';if(node.replaceData(1,2,'\udfff')!==undefined||node.data!=='A\udfffB'||node.nodeValue!==node.data||node.textContent!==node.data||node.ownerDocument!==owner||copy.data!==value||copy.ownerDocument!==owner)throw 'replace exact native aliases and clone owners';var records=watch.takeRecords();if(records.length!==4||records[0].oldValue!==value||records[1].oldValue!=='A\ud83d\ude00B'||records[2].oldValue!=='A\ud83d\ud800\ude00B'||records[3].oldValue!=='A\ud83d\ude00B')throw 'one actual old-value record per operation';for(var record of records){if(record.target!==node||record.type!=='characterData')throw 'genuine mutation record target';}watch.disconnect();}}
"#);
}
#[test]
fn character_splice_live_ranges_follow_removed_interval_tail_shift_and_insert_boundaries(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"var text=document.createTextNode('abcdef'),ranges=[];for(var i=0;i<=6;i++){var range=document.createRange();range.setStart(text,i);range.collapse(true);ranges.push(range);}text.replaceData(2,2,'XYZ');var expected=[0,1,2,2,2,6,7];for(var i=0;i<ranges.length;i++){if(ranges[i].startContainer!==text||ranges[i].endContainer!==text||ranges[i].startOffset!==expected[i]||ranges[i].endOffset!==expected[i])throw 'replace live Range positions';}text.insertData(2,'Q');expected=[0,1,2,2,2,7,8];for(var i=0;i<ranges.length;i++){if(ranges[i].startOffset!==expected[i]||ranges[i].endOffset!==expected[i])throw 'insertion boundary stays and tail shifts';}text.deleteData(1,999);expected=[0,1,1,1,1,1,1];if(text.data!=='a')throw 'clamped deletion';for(var i=0;i<ranges.length;i++){if(ranges[i].startOffset!==expected[i]||ranges[i].endOffset!==expected[i])throw 'deleted interval collapses to offset';}text.appendData('z');if(text.data!=='az')throw 'append data';for(var i=0;i<ranges.length;i++){if(ranges[i].startOffset!==expected[i]||ranges[i].endOffset!==expected[i])throw 'append at endpoint does not move boundary';}var unicode=document.createTextNode('A\ud83d\ude00B'),r=document.createRange();r.setStart(unicode,3);r.setEnd(unicode,4);unicode.insertData(1,'\ud800');if(r.startOffset!==4||r.endOffset!==5)throw 'Range insertion counts UTF16 units';unicode.replaceData(2,2,'Z');if(r.startOffset!==2||r.endOffset!==4||unicode.data!=='A\ud800ZB')throw 'UTF16 removed tail endpoint and following offset';"#);
}
#[test]
fn character_splice_noop_operations_still_observe_and_data_arguments_use_domstring_rules(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var text=document.createTextNode('held'),watch=new MutationObserver(function(){});watch.observe(text,{characterData:true,characterDataOldValue:true});text.appendData('');text.insertData(4,'');text.deleteData(4,999);text.replaceData(0,0,'');var records=watch.takeRecords();if(text.data!=='held'||records.length!==4)throw 'zero-length replacements still queue records';for(var record of records){if(record.oldValue!=='held'||record.target!==text)throw 'no-op original old value';}text.appendData(null);text.appendData(undefined);if(text.data!=='heldnullundefined')throw 'method DOMString is not legacy-null data setter';text.replaceData(0,4,BigInt(10));if(text.data!=='10nullundefined')throw 'BigInt data uses ToString';text.deleteData(4294967296,2);if(text.data!=='nullundefined')throw 'unsigned offset wraps';text.insertData(0,'held');text.replaceData(4294967297.9,1.9,'X');if(text.data!=='hXldnullundefined')throw 'unsigned-long numeric conversion';");
}
#[test]
fn character_splice_argument_effects_precede_current_bounds_and_exception_order(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var text=document.createTextNode('old'),trace='',watch=new MutationObserver(function(){});watch.observe(text,{characterData:true});var caught=false;try{text.replaceData({valueOf:function(){trace+='offset|';return 99;}},{valueOf:function(){trace+='count|';return 1;}},{toString:function(){trace+='data|';text.data='expanded';return 'Z';}});}catch(e){caught=e instanceof DOMException&&e.name==='IndexSizeError';}if(!caught||trace!=='offset|count|data|'||text.data!=='expanded'||watch.takeRecords().length!==1)throw 'current bounds after all conversions and retained author effect';var result=text.insertData(2,{toString:function(){text.data='abcdef';return 'Q';}});if(result!==undefined||text.data!=='abQcdef'||watch.takeRecords().length!==2)throw 'insert reads current source after data conversion';text.appendData({toString:function(){text.data='X';return 'Y';}});if(text.data!=='XY'||watch.takeRecords().length!==2)throw 'append reads current length';var calls=0,caught=false;try{CharacterData.prototype.insertData.call(document.body,{valueOf:function(){calls++;return 0;}},{toString:function(){calls++;return 'x';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'native brand precedes conversion';caught=false;try{text.replaceData(99,1,Symbol('data'));}catch(e){caught=e instanceof TypeError;}if(!caught||text.data!=='XY'||watch.takeRecords().length)throw 'data conversion error precedes offset validation';var sentinel={},seen=null;try{text.insertData(99,{toString:function(){throw sentinel;}});}catch(e){seen=e;}if(seen!==sentinel||text.data!=='XY')throw 'author exception preserved';");
}
#[test]
fn character_splice_captured_child_writer_origin_precedes_numeric_and_string_conversion(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var saved=frame.contentWindow.CharacterData.prototype.replaceData,text=document.createTextNode('held'),calls=0,offset={valueOf:function(){calls++;return 1;}},count={valueOf:function(){calls++;return 2;}},data={toString:function(){calls++;return 'X';}};if(saved.call(text,offset,count,data)!==undefined||text.data!=='hXd'||calls!==3)throw 'actual captured writer';");page.set_location(&crate::navigation::address("https://other-character-splice.test/",&crate::navigation::Location::home()).unwrap());let before=(doc.nodes.len(),page.state.retained,page.state.dom_commits);assert_eq!(page.console_eval(&mut doc,&mut forms,"saved.call(text,offset,count,data);").errors,1);assert!(page.report().contains("same-origin")||page.report().contains("Security"),"{}",page.report());assert_eq!((doc.nodes.len(),page.state.retained,page.state.dom_commits),before);run(&mut doc,&mut forms,&mut page,"if(calls!==3||text.data!=='hXd')throw 'origin before writer argument conversion';");
}

#[test]
fn character_splice_late_native_refusal_keeps_data_ranges_observers_and_recovers(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var text=document.createTextNode('held'),range=document.createRange();range.setStart(text,1);range.setEnd(text,3);var delivered=0,watch=new MutationObserver(function(){delivered++;});watch.observe(text,{characterData:true,characterDataOldValue:true});");let before=(doc.nodes.len(),page.state.retained,page.state.dom_commits);let limit=page.state.retained_limit;page.state.retained_limit=page.state.retained;assert_eq!(page.console_eval(&mut doc,&mut forms,"text.replaceData(1,2,'expanded replacement');").errors,1);assert_eq!((doc.nodes.len(),page.state.retained,page.state.dom_commits),before);page.state.retained_limit=limit;run(&mut doc,&mut forms,&mut page,"if(text.data!=='held'||range.startContainer!==text||range.endContainer!==text||range.startOffset!==1||range.endOffset!==3||watch.takeRecords().length||delivered)throw 'late refusal has no data Range or observer prefix';text.replaceData(1,2,'XYZ');var records=watch.takeRecords();if(text.data!=='hXYZd'||range.startOffset!==1||range.endOffset!==1||records.length!==1||records[0].oldValue!=='held'||records[0].target!==text||delivered)throw 'fresh splice recovery with original old value';");
}
